#define MAX_STEPS 250
#define FAR_DIST 999.0
#define EPS 0.001

#define LEFT    vec3(1.0, 0.0, 0.0) 
#define UP      vec3(0.0, 1.0, 0.0)
#define FORWARD vec3(0.0, 0.0, 1.0)

#define GAMMA 2.2


vec3 look_at(vec3 p, vec3 dy, vec3 dz)
{
    vec3 dx = cross(dz, dy);
    dy = cross(dx, dz);

    return p * mat3(
        normalize(dx),
        normalize(dy),
        normalize(dz)
    );
}

float sd_sphere( vec3 p, float r )
{
  return length(p)-r;
}


float sd_box( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}


float scene(vec3 p)
{   
    p += vec3(0.0, 0.0, -1.0);

    vec2 mouse_p = (iMouse.xy / iResolution.xy - 0.5) * 2.0;
    vec3 look_d = vec3(mouse_p, -1.0);

    p = look_at(p, UP, look_d);

    return sd_box(p, vec3(0.2));
}


//get normals from: https://iquilezles.org/articles/normalsSDF/
vec3 get_normal(vec3 p)
{
    const float eps = 0.0001; // or some other value
    const vec2 h = vec2(eps,0);
    int obj_id = -1;
    return normalize( vec3(scene(p+h.xyy) - scene(p-h.xyy),
                           scene(p+h.yxy) - scene(p-h.yxy),
                           scene(p+h.yyx) - scene(p-h.yyx) ) );
}

float shading(vec3 p, vec3 n, vec3 ld)
{
    return max(dot(n, ld), 0.01);
}

vec3 march(vec3 ro, vec3 rd)
{
    float d = 0.0;
    vec3 p = ro;
    bool hit = false;

    for(int i = 0; i < MAX_STEPS; i++)
    {
        d = scene(p);
        p += rd *  d * 0.5;

        if(d < EPS)
        {
            hit = true;
            break;
        }else if(dot(p, p) > FAR_DIST)  break;
    }

    //render
    vec3 ld = normalize(vec3(1.0, 1.0, -1.0));
    vec3 n = get_normal(p);
    vec3 col = vec3(0.05);

    if (hit)
        col = vec3(0.8, 0.0, 0.0) * pow(shading(p, n, ld), 1.0/GAMMA);

    return col;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.yy;
    uv -= vec2(0.88, 0.5);

    vec3 ro = vec3(0.0, 0.0, 0.0);
    vec3 rd = normalize(vec3(uv, 0.0) - vec3(0.0, 0.0, -1.0));
    vec3 col = march(ro, rd);

    // Output to screen
    fragColor = vec4(col,1.0);
}
